SELECT o.SalesOrderId,l.SalesOrderLineId FROM #SourceLineMap m JOIN dbo.SalesOrder o ON o.OrderNumber=m.OrderNumber JOIN dbo.SalesOrderLine l ON l.SourceLineCode=m.SourceLineCode;
SELECT p.ProductId,l.SalesOrderLineId FROM #SourceLineMap m JOIN dbo.Product p ON p.ProductCode=m.ProductCode JOIN dbo.SalesOrderLine l ON l.SourceLineCode=m.SourceLineCode;
DROP TABLE #SourceLineMap;
CREATE TABLE #OrderCustomer(OrderNumber varchar(30) PRIMARY KEY,CustomerCode varchar(30));
