SELECT c.CustomerId,o.SalesOrderId FROM #OrderCustomer m JOIN dbo.Customer c ON c.CustomerCode=m.CustomerCode JOIN dbo.SalesOrder o ON o.OrderNumber=m.OrderNumber;
DROP TABLE #OrderCustomer;
